                            Token::AndAnd
                            | Token::At
                            | Token::BangEqual
                            | Token::BitAnd
                            | Token::BitOr
                            | Token::BitXor
                            | Token::Comma
                            | Token::Dot
                            | Token::EOF
                            | Token::Else
                            | Token::Equal
                            | Token::EqualEqual
